HC_CorkboardOpen::
	xor a
	ld [wMenuScrollPosition], a
	ret

HC_CorkCount:
; a = how many of the HC_CORK_NOTES pages are pinned
	xor a
	ld [wTextDecimalByte], a
	ld hl, HC_CorkTable
	ld a, HC_CORK_NOTES
.count
	push af
	ld e, [hl]
	inc hl
	ld d, [hl]
	inc hl
	inc hl
	inc hl
	push hl
	ld b, CHECK_FLAG
	call EventFlagAction
	ld a, c
	and a
	jr z, .no
	ld hl, wTextDecimalByte
	inc [hl]
.no
	pop hl
	pop af
	dec a
	jr nz, .count
	ld a, [wTextDecimalByte]
	ret

HC_CorkboardPage::
; wScriptVar = the page chosen (1 .. HC_CORK_NOTES + 1), 0 when the player left the board
	call LoadStandardMenuHeader
	call ClearSprites ; the player and the people of the map must not show through the page
	hlcoord 0, 0
	ld bc, SCREEN_AREA
	ld a, ' '
	call ByteFill
	hlcoord 0, 0
	lb bc, 1, 18
	call Textbox
	hlcoord 1, 1
	ld de, HC_CorkTitle
	call PlaceString
	call HC_CorkCount
	ld [wTextDecimalByte], a
	hlcoord 11, 1
	ld de, wTextDecimalByte
	lb bc, 1, 2
	call PrintNum
	hlcoord 13, 1
	ld de, HC_CorkPinned
	call PlaceString
	hlcoord 0, 3
	lb bc, 13, 18
	call Textbox
	ld hl, HC_CorkMenuHeader
	call CopyMenuHeader
	call ScrollingMenu
	ld a, [wMenuJoypad]
	cp PAD_B
	jr z, .cancel
	ld a, [wMenuSelection]
	jr .done
.cancel
	xor a
.done
	ld [wScriptVar], a
	call CloseWindow
	ret

HC_CorkMenuHeader:
	db MENU_BACKUP_TILES ; flags
	menu_coords 1, 4, 18, 16
	dw .MenuData
	db 1 ; default option

.MenuData:
	db SCROLLINGMENU_DISPLAY_ARROWS ; flags
	db 6, 0 ; rows, columns
	db SCROLLINGMENU_ITEMS_NORMAL ; item format
	dba .Pages
	dba HC_CorkPrint
	dba NULL
	dba NULL

.Pages:
	db HC_CORK_NOTES + 1
for x, HC_CORK_NOTES + 1
	db x + 1
endr
	db -1

HC_CorkPrint:
	push de
	ld a, [wMenuSelection]
	cp HC_CORK_NOTES + 1
	jr z, .whole
	dec a
	ld hl, HC_CorkTable
	ld bc, 4
	call AddNTimes
	ld e, [hl]
	inc hl
	ld d, [hl]
	inc hl
	push hl
	ld b, CHECK_FLAG
	call EventFlagAction
	pop hl
	ld a, c
	and a
	jr z, .blank
	ld e, [hl]
	inc hl
	ld d, [hl]
	jr .print
.whole
	call HC_CorkCount
	cp HC_CORK_NOTES
	ld de, HC_CorkWhole
	jr z, .print
.blank
	ld de, HC_CorkBlank
.print
	pop hl
	call PlaceString
	ret

