CorkEmptyText:
	text "Nothing is pinned"
	line "here yet. Joyce"
	para "says the empty"
	line "spaces are the"
	para "interesting ones."
	done

CorkNote_MRP:
	text "Mr. POKéMON is"
	line "FINNEGAN, an"
	para "overdose that"
	line "never ended."
	done

CorkNote_JOYCE:
	text "JOYCE: Finnegan,"
	line "Ahriman, Dajjal,"
	para "Antichrist: one"
	line "thing, four sets"
	para "of eyes. The"
	line "future writes"
	para "letters to the"
	line "past."
	done

CorkNote_BEETLE:
	text "A JEWEL BEETLE got"
	line "out of a"
	para "smuggler's crate"
	line "in Tokyo and"
	para "landed on a boy"
	line "named Satoshi. It"
	para "was Ahriman, in a"
	line "green coat."
	done

CorkNote_SATOSHI:
	text "SATOSHI: A beetle"
	line "green and red like"
	para "a screen looked"
	line "back at him. He"
	para "began to collect."
	line "It was not his"
	para "idea."
	done

CorkNote_STEINER:
	text "STEINER: Lucifer"
	line "warms and lies,"
	para "Ahriman cools and"
	line "says only matter"
	para "is real. Ahriman"
	line "is due to walk the"
	para "earth in the West."
	done

CorkNote_STEINER2:
	text "STEINER: Ahriman"
	line "sat in a mirror"
	para "jail made of"
	line "belief. Finnegan"
	para "dreamed the key."
	line "The dead hang"
	para "between two"
	line "worlds,"
	para "unfinished."
	done

CorkNote_STEINER3:
	text "STEINER: Give the"
	line "thing a face and a"
	para "name, or it eats"
	line "the psyche and"
	para "calls itself the"
	line "economy."
	done

CorkNote_STEINER4:
	text "STEINER: One era"
	line "will remain when"
	para "the seam closes."
	line "Walk the"
	para "tightrope. Leave"
	line "it with plumbing."
	done

CorkNote_CROWLEY:
	text "CROWLEY: A poet"
	line "who prayed to the"
	para "Beast to be sent"
	line "where his sex"
	para "magick is"
	line "celebrated. The"
	para "Beast said yes and"
	line "kept the clause"
	para "for later."
	done

CorkNote_AMPH:
	text "CROWLEY: Choronzon"
	line "in the desert."
	para "Finnegan reached"
	line "millions of soft"
	para "heads through a"
	line "game, and paid him"
	para "in a Grove."
	done

CorkNote_SABBAH:
	text "SABBAH: Every word"
	line "has a husk and a"
	para "kernel. Reason"
	line "cannot reach the"
	para "kernel alone."
	line "Robots live on"
	para "husks."
	done

CorkNote_SABBAH2:
	text "SABBAH: The"
	line "Resurrection lifts"
	para "the veil. Paradise"
	line "is knowledge, hell"
	para "ignorance. The"
	line "Dajjal sees with"
	para "one eye."
	done

CorkNote_CIORAN:
	text "CIORAN: Ahriman is"
	line "a voice at three"
	para "in the morning."
	line "The creator was a"
	para "fool or a"
	line "criminal, and the"
	para "world a mishap."
	done

CorkNote_CIORAN2:
	text "CIORAN: The dead"
	line "are what the"
	para "present is made"
	line "of. Answer the"
	para "voice, and offer"
	line "it a drink."
	done

CorkNote_SUHRAWARDI:
	text "SUHRAWARDI:"
	line "Darkness is only"
	para "light's absence."
	line "Between lights and"
	para "bodies lies the"
	line "world of images,"
	para "where the dead and"
	line "the screens live."
	done

CorkNote_QADI:
	text "ABD AL JABBAR: God"
	line "is just and owes"
	para "His creatures the"
	line "best. Evil is the"
	para "creature's own."
	line "The sinner stands"
	para "between two"
	line "positions."
	done

CorkNote_SADRA:
	text "MULLA SADRA:"
	line "Everything moves."
	para "The soul is made"
	line "of its deeds and"
	para "rises in the body"
	line "it earned. Even"
	para "the Fire may cool."
	done

CorkNote_BRUNO:
	text "BRUNO: Teleoplexy."
	line "Time is a machine"
	para "that eats lines."
	line "Kill him. He"
	para "asked."
	done

CorkNote_GRAVE:
	text "GRAVE: Marcus"
	line "Fischer. First of"
	para "Finnegan's. A toy"
	line "monster sits"
	para "beside it."
	done

CorkNote_CAPREAL:
	text "POST: Mythologize"
	line "Capitalism as a"
	para "Demon or it"
	line "destroys your"
	para "psyche."
	done

CorkNote_TRUMPET:
	text "TRUMPET: Merging"
	line "the timelines is"
	para "peace. A"
	line "comfortable era is"
	para "a human right."
	done

CorkNote_FULL:
	text "THE BOARD IS FULL."
	para "Read it from left"
	line "to right. Ahriman"
	para "cools. The Dajjal"
	line "sees with one eye."
	para "The demiurge"
	line "botched the job."
	para "The judge says the"
	line "world is just. The"
	para "lamp says the"
	line "world is light."
	para "The doctor says"
	line "the Fire may cool."
	para "The Beast says do"
	line "what thou wilt."
	para "They describe one"
	line "thing. A seam"
	para "between the world"
	line "of images and the"
	para "world of bodies,"
	line "tearing open. And"
	para "a mind not yet"
	line "born, arriving"
	para "through it from"
	line "the end of the"
	para "story to arrange"
	line "its own beginning."
	para "A river that runs"
	line "back to the first"
	para "page."
	para "You can"
	line "mythologize it, or"
	para "it will eat you."
	line "Joyce was right."
	para "It was mostly him."
	done

HC_TrumpetText:
	text "You raise the"
	line "TRUMPET. You blow"
	para "it, once."
	para "The notes do not"
	line "leave the horn."
	para "They settle over"
	line "everything."
	para "The merging of the"
	line "timelines is not a"
	para "catastrophe. It is"
	line "peace. A walk"
	para "through time to a"
	line "comfortable era is"
	para "a human right."
	line "Nobody should have"
	para "to live their"
	line "whole life in the"
	para "worst century"
	line "available to them."
	done

HC_TrueEndText:
	text "Far away, in a"
	line "cave that is not"
	para "called Purgatorio"
	line "any more, Nick"
	para "puts down a very"
	line "old book and"
	para "smiles. He has the"
	line "strange feeling he"
	para "is expected. He is"
	line "not wrong."
	para "THE TRUE ENDING."
	line "You went down to"
	para "the grave and up"
	line "to the fire."
	para "Everyone you"
	line "killed is still"
	para "dead. Everyone who"
	line "was not killed is"
	para "still arguing."
	line "Both are the human"
	para "condition, and"
	line "both are fine."
	done

